create extension if not exists pgcrypto;
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,native_language text default 'ar',target_level text default 'A1',current_level text default 'A0',daily_goal_minutes int default 180,streak_count int default 0,total_xp int default 0,created_at timestamptz default now());
create table if not exists skills(id bigserial primary key,user_id uuid references profiles(id) on delete cascade,skill_name text check(skill_name in('vocabulary','grammar','listening','reading','writing','speaking','pronunciation','shadowing')),level text default 'A0',mastery_percent int default 0 check(mastery_percent between 0 and 100),xp int default 0,updated_at timestamptz default now(),unique(user_id,skill_name));
create table if not exists levels(id serial primary key,name text unique check(name in('A0','A1','A2','B1','B2')),order_num int,unlock_requirements jsonb,total_lessons int,total_hours int);
create table if not exists modules(id serial primary key,level_id int references levels(id) on delete cascade,title text,order_num int,is_locked boolean default true,unlock_criteria jsonb);
create table if not exists lessons(id serial primary key,module_id int references modules(id) on delete cascade,title text,type text check(type in('vocabulary','grammar','listening','reading','writing','speaking','pronunciation','exam')),content jsonb,video_url text,duration_minutes int,order_num int,is_locked boolean default true);
create table if not exists lesson_completions(id bigserial primary key,user_id uuid references profiles(id) on delete cascade,lesson_id int references lessons(id) on delete cascade,completed_at timestamptz default now(),score int,time_spent_seconds int,unique(user_id,lesson_id));
create table if not exists vocabulary_items(id serial primary key,level text check(level in('A1','A2','B1','B2')),german_word text not null,arabic_translation text not null,part_of_speech text,article text check(article in('der','die','das') or article is null),plural_form text,example_sentence text not null,example_translation text,audio_url text,image_url text,topic text,frequency_rank int,is_essential boolean default false);
create table if not exists grammar_concepts(id serial primary key,level text,title text,arabic_explanation text not null,german_examples jsonb,rules text[],exceptions text[],related_concepts int[],video_url text,practice_exercises jsonb);
create table if not exists listening_tracks(id serial primary key,level text,title text,audio_url text,transcript text not null,arabic_translation text,comprehension_questions jsonb,vocabulary_ids int[],duration_seconds int);
create table if not exists reading_texts(id serial primary key,level text check(level in('A1','A2','B1','B2')),title text,german_text text not null,arabic_translation text not null,vocabulary_glossary jsonb,comprehension_questions jsonb,word_count int,estimated_minutes int,genre text);
create table if not exists mistake_bank(id bigserial primary key,user_id uuid references profiles(id) on delete cascade,question_type text,question_content jsonb,user_answer jsonb,correct_answer jsonb,explanation text,created_at timestamptz default now(),resolved boolean default false,resolved_at timestamptz);
create table if not exists fsrs_reviews(id bigserial primary key,user_id uuid references profiles(id) on delete cascade,card_id int references vocabulary_items(id) on delete cascade,stability double precision default 0,difficulty double precision default 0,elapsed_days int default 0,scheduled_days int default 0,reps int default 0,lapses int default 0,state text check(state in('New','Learning','Review','Relearning')),last_review_at timestamptz,due_at timestamptz,unique(user_id,card_id));
create table if not exists conversations(id uuid primary key default gen_random_uuid(),user_id uuid references profiles(id) on delete cascade,scenario text,level text,messages jsonb,corrections jsonb,created_at timestamptz default now());
create table if not exists writing_submissions(id uuid primary key default gen_random_uuid(),user_id uuid references profiles(id) on delete cascade,prompt text,submission text,ai_feedback jsonb,score int,created_at timestamptz default now());
create table if not exists pronunciation_attempts(id uuid primary key default gen_random_uuid(),user_id uuid references profiles(id) on delete cascade,word text,audio_url text,score double precision check(score between 0 and 100),phoneme_scores jsonb,created_at timestamptz default now());
create table if not exists exams(id serial primary key,level text check(level in('Goethe_A1','Goethe_A2','Goethe_B1','DTZ_B1')),sections jsonb,total_duration_minutes int,passing_score int default 60);
create table if not exists exam_attempts(id uuid primary key default gen_random_uuid(),user_id uuid references profiles(id) on delete cascade,exam_id int references exams(id),section_scores jsonb,total_score int,passed boolean,taken_at timestamptz default now());
create table if not exists daily_plans(id bigserial primary key,user_id uuid references profiles(id) on delete cascade,plan_date date,focus_skill text,planned_minutes int,completed_minutes int default 0,lessons_completed jsonb,created_at timestamptz default now(),unique(user_id,plan_date));
alter table profiles enable row level security; alter table skills enable row level security; alter table lesson_completions enable row level security; alter table mistake_bank enable row level security; alter table fsrs_reviews enable row level security; alter table conversations enable row level security; alter table writing_submissions enable row level security; alter table pronunciation_attempts enable row level security; alter table exam_attempts enable row level security; alter table daily_plans enable row level security;
alter table levels enable row level security; alter table modules enable row level security; alter table lessons enable row level security; alter table vocabulary_items enable row level security; alter table grammar_concepts enable row level security; alter table listening_tracks enable row level security; alter table reading_texts enable row level security; alter table exams enable row level security;
create policy "profiles own select" on profiles for select using(auth.uid()=id); create policy "profiles own update" on profiles for update using(auth.uid()=id); create policy "profiles own insert" on profiles for insert with check(auth.uid()=id); create policy "profiles own delete" on profiles for delete using(auth.uid()=id);
do $$ declare t text; begin foreach t in array array['skills','lesson_completions','mistake_bank','fsrs_reviews','conversations','writing_submissions','pronunciation_attempts','exam_attempts','daily_plans'] loop execute format('create policy %I on %I for select using (auth.uid() = user_id)',t||'_own_select',t); execute format('create policy %I on %I for insert with check (auth.uid() = user_id)',t||'_own_insert',t); execute format('create policy %I on %I for update using (auth.uid() = user_id) with check (auth.uid() = user_id)',t||'_own_update',t); execute format('create policy %I on %I for delete using (auth.uid() = user_id)',t||'_own_delete',t); end loop; end $$;
do $$ declare t text; begin foreach t in array array['levels','modules','lessons','vocabulary_items','grammar_concepts','listening_tracks','reading_texts','exams'] loop execute format('create policy %I on %I for select to authenticated using (true)',t||'_authenticated_read',t); end loop; end $$;
create index if not exists idx_fsrs_due on fsrs_reviews(user_id,due_at); create index if not exists idx_mistakes_open on mistake_bank(user_id,resolved,created_at desc); create index if not exists idx_vocab_level_topic on vocabulary_items(level,topic);
